from dataclasses import dataclass


@dataclass
class Item:
    sku: str
    quantity: int
    unit_price_cents: int


@dataclass
class Customer:
    email: str
    country: str = "DE"
    vip: bool = False


@dataclass
class Order:
    id: int
    items: list[Item]
    coupon: str | None = None
    status: str = "new"
    total_cents: int = 0
from decimal import Decimal

TAX_RATES = {
    "DE": Decimal("0.19"),
    "FR": Decimal("0.20"),
    "CH": Decimal("0.081"),
}
DEFAULT_TAX_RATE = Decimal("0.21")


def tax_rate(country: str) -> Decimal:
    return TAX_RATES.get(country, DEFAULT_TAX_RATE)
from shop.errors import OutOfStock


class Inventory:
    def __init__(self, stock: dict[str, int]) -> None:
        self._stock = dict(stock)
        self._reserved: dict[str, int] = {}
        self.log: list[tuple[str, str, int]] = []

    def available(self, sku: str) -> int:
        return self._stock.get(sku, 0) - self._reserved.get(sku, 0)

    def reserve(self, sku: str, quantity: int) -> None:
        if self.available(sku) < quantity:
            raise OutOfStock(sku)
        self._reserved[sku] = self._reserved.get(sku, 0) + quantity
        self.log.append(("reserve", sku, quantity))

    def release(self, sku: str, quantity: int) -> None:
        self._reserved[sku] = self._reserved.get(sku, 0) - quantity
        self.log.append(("release", sku, quantity))

    def commit(self, sku: str, quantity: int) -> None:
        self._reserved[sku] = self._reserved.get(sku, 0) - quantity
        self._stock[sku] = self._stock.get(sku, 0) - quantity
        self.log.append(("commit", sku, quantity))

    def restock(self, sku: str, quantity: int) -> None:
        self._stock[sku] = self._stock.get(sku, 0) + quantity
        self.log.append(("restock", sku, quantity))
class CouponBook:
    """Percentage coupons with a limited number of redemptions."""

    def __init__(self, coupons: dict[str, tuple[int, int]]) -> None:
        self._percent = {code: percent for code, (percent, _) in coupons.items()}
        self._remaining = {code: uses for code, (_, uses) in coupons.items()}

    def discount_percent(self, code: str) -> int | None:
        if self._remaining.get(code, 0) <= 0:
            return None
        return self._percent[code]

    def redeem(self, code: str) -> None:
        self._remaining[code] -= 1
class OutOfStock(Exception):
    def __init__(self, sku: str) -> None:
        super().__init__(sku)
        self.sku = sku


class PaymentDeclined(Exception):
    pass


class OrderRejected(Exception):
    pass
